import{_ as a,o as e,c as o,ai as l}from"./chunks/framework.scx6l_IK.js";const q=JSON.parse('{"title":"收功的方法","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/修行即生活-收功.md","filePath":"60-原文段落/修行即生活-收功.md","lastUpdated":1778155802000}'),r={name:"60-原文段落/修行即生活-收功.md"};function i(u,t,_,c,n,s){return e(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="收功的方法" tabindex="-1">收功的方法 <a class="header-anchor" href="#收功的方法" aria-label="Permalink to &quot;收功的方法&quot;">​</a></h1><blockquote><p>来源：修行即生活（20090111b）</p></blockquote><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><blockquote><p>&quot;收功其实是使我们的身心从比较安静、比较放松的状态恢复到常态。收功的原理就是这样。其实收功就跟我们早上起床，慢慢起来，慢慢穿衣服，不要说一动你就从床上跳起来，然后就去跑步了，做激烈运动，那是不行的。收功的过程就是从静态慢慢恢复到动态的过程。当你们有一天功夫非常纯熟的人和功夫很高深的人，他们收不收功都没所谓。但是中等阶段的人一般还是要收功。&quot;</p></blockquote><blockquote><p>&quot;收功经常是这样，你们原来轻轻意守手指脚趾，收功的时候其实也是同时意守手脚，只是加个意念说&#39;我要收功了，我要收功了&#39;，心里反复这么想。等到精神比较清醒了，然后全身关节先做广播体操、上体育课活动放松身体一样，全身关节活动活动，弯弯腰、伸伸腿、转转头、甩甩手腕、膝盖、脚踝这些地方都活动活动。先整个身体轻轻活动一遍，让它适应从静态到动态。这个过渡就是这个作用。也不用特别说引气收进丹田，不用。你可以永远轻轻意守手脚，只是身体从静坐到要自然活动，我们要让它适应适应，精神也是这样，身体也是这样，都是让它适应适应，就是这个作用。&quot;</p></blockquote><blockquote><p>&quot;其实收功还是起床之后，有一个适应过程都很好的，都是好习惯。&quot;</p></blockquote><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to &quot;关键要点&quot;">​</a></h2><ul><li>收功=身心从静态过渡到动态的缓冲过程</li><li>默念&quot;我要收功了&quot;→精神清醒→全身关节活动</li><li>不需要特别引气收进丹田</li><li>功夫高深后收不收功都可以</li></ul>',8)])])}const p=a(r,[["render",i]]);export{q as __pageData,p as default};
